before_request=1;function ajax_submit_form(form_id,submit_url){if(before_request==0)return false;if(submit_url.indexOf("?")>-1){submit_url+="&"}else{submit_url+="?"}submit_url+="_ajax=1";$("[id^='err_']").hide();$.ajax({type:"POST",url:submit_url,data:$("#"+form_id).serialize(),error:function(e){layer.alert(e.responseText,{icon:5,title:false});return false},success:function(v){before_request=1;var v=eval("("+v+")");if(v.hasOwnProperty("status")){layer.msg(v.msg,{icon:6,time:1e3},function(){if(v.status==1){if(v.hasOwnProperty("data")){if(v.data.hasOwnProperty("url")){location.href=v.data.url}else{location.href=location.href}}else{location.href=location.href}return true}});if(v.status==0){return false}}for(var i in v["data"]){$("#err_"+i).text(v["data"][i]).show()}}});before_request=0}function convert_url(url){if(url){url=url.replace(".html","")}return url}
